package bench

import (
	"bytes"
	"context"
	"fmt"
	"io"
	"os"
	"os/exec"
	"path/filepath"
	"strings"
)

// A golden is the Go source bento generates for a workload, checked in next to
// the TypeScript as workloads/<area>/<name>.golden. Storing it turns a benchmark
// run into a record of both the timings and the code that produced them: a
// reader can see exactly what bento lowered each workload to, and a diff on the
// golden shows when a compiler change moved the generated code. Each golden
// opens with bento's "Code generated by bento <version> ..." header, so the file
// itself names the build that wrote it.

// GoldenEmitArgs drive bento to print a workload's generated Go to stdout
// without linking a binary. They mirror AOTBuildArgs but swap the build for an
// emit, so a golden is captured with the same compiler that times the workload.
var GoldenEmitArgs = []string{"build", "--emit-go", "-"}

// GoldenPath is where a workload's generated Go is checked in: next to the
// TypeScript with the extension swapped for .golden, so compute/coercion.ts
// pairs with compute/coercion.golden and the code sits beside the source it came
// from.
func GoldenPath(w Workload) string {
	return strings.TrimSuffix(w.Path, filepath.Ext(w.Path)) + ".golden"
}

// EmitGolden compiles one workload with bento --emit-go, captures the generated
// Go, and writes it to the workload's .golden file, but only when the content
// differs from what is already there. The update-only rule keeps a rerun that
// changes nothing from rewriting the file or dirtying its git status; the return
// reports whether the golden was written. A compile failure comes back with
// bento's own message so the caller can name the workload bento cannot lower
// yet, rather than leaving a stale golden in place.
func EmitGolden(ctx context.Context, bentoBin string, w Workload) (bool, error) {
	args := append(append([]string{}, GoldenEmitArgs...), w.Path)
	cmd := exec.CommandContext(ctx, bentoBin, args...)
	var stdout, stderr bytes.Buffer
	cmd.Stdout = &stdout
	cmd.Stderr = &stderr
	if err := cmd.Run(); err != nil {
		msg := strings.TrimSpace(stderr.String())
		if msg == "" {
			msg = err.Error()
		}
		return false, fmt.Errorf("%s: %s", w.Name, msg)
	}

	next := stdout.Bytes()
	path := GoldenPath(w)
	if current, err := os.ReadFile(path); err == nil && bytes.Equal(current, next) {
		return false, nil
	}
	if err := os.WriteFile(path, next, 0o644); err != nil {
		return false, err
	}
	return true, nil
}

// EmitGoldens refreshes the .golden of every workload bento can lower and
// returns how many files it changed. A workload bento cannot compile yet is
// reported to log and skipped rather than failing the whole sweep, so every
// golden that can be produced still lands. It is meant to run alongside a
// benchmark, so a rerun keeps the checked-in Go in step with the timings.
func EmitGoldens(ctx context.Context, bentoBin string, workloads []Workload, log io.Writer) int {
	updated := 0
	for _, w := range workloads {
		changed, err := EmitGolden(ctx, bentoBin, w)
		switch {
		case err != nil:
			logf(log, "  golden %s/%s skipped: %v\n", w.Category, w.Name, err)
		case changed:
			updated++
			logf(log, "  golden %s/%s updated\n", w.Category, w.Name)
		}
	}
	return updated
}
